import Link from "next/link"

interface SchoolCardProps {
  id?: number
  title: string
  description: string
  icon: string
  gradient?: string
  link: string
  isActive?: boolean
}

export default function SchoolCard({ title, description, icon, gradient, link, isActive }: SchoolCardProps) {
  return (
    <Link href={link}>
      <div
        style={gradient ? { background: gradient } : undefined}
        className={`border border-border rounded-lg p-6 h-full hover:shadow-lg hover:border-primary/30 transition cursor-pointer group relative bg-white`}
      >
        {isActive && (
          <div className="absolute top-3 right-3">
            <span className="inline-block bg-accent text-accent-foreground text-xs font-bold px-2 py-1 rounded-full">
              En cours
            </span>
          </div>
        )}
        <div className="text-4xl mb-4 group-hover:scale-110 transition">{icon}</div>
        <h3 className="text-xl font-bold text-primary mb-3 group-hover:text-accent transition">{title}</h3>
        <p className="text-foreground/70 text-sm leading-relaxed">{description}</p>
        <div className="mt-4 text-primary text-sm font-semibold group-hover:translate-x-1 transition">
          En savoir plus →
        </div>
      </div>
    </Link>
  )
}
