import Image from 'next/image';

interface TeamMemberProps {
  name: string;
  role: string;
  imageSrc: string;
  className?: string;
}

export default function TeamMember({ name, role, imageSrc, className = '' }: TeamMemberProps) {
  return (
    <div className={`flex flex-col items-center text-center ${className}`}>
      <div className="w-48 h-48 md:w-56 md:h-56 rounded-full overflow-hidden border-4 border-primary/20 mb-4">
        <Image 
          src={imageSrc}
          alt={name}
          width={224}
          height={224}
          className="w-full h-full object-cover"
        />
      </div>
      <h3 className="text-xl font-semibold text-foreground">{name}</h3>
      <p className="text-foreground/70">{role}</p>
    </div>
  );
}
